  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (437::BIGINT, 'no importa que curso sea, este profe siempre va a ser la mejor opción. Ayuda mucho, explica excelente y los exámenes son bastante fáciles'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2026-10-28T00:00:00+00:00'::TIMESTAMPTZ, '3cf4f490a6600eeb7f9e9a223b86f68a0908a17a4372e3e455b2c85a97fe8ed7'::TEXT, ARRAY[1745]::BIGINT[]),
    (437::BIGINT, 'Exelente profe y un 100 como persona, eso si, califica de manera dificil pero justa, aun asi es un exito como profe, no lo va a defraudar.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2026-01-13T00:00:00+00:00'::TIMESTAMPTZ, '95ccddddd02d573e1ed549328cce4b4a2a828a3391ab76ba104434f19cccbed9'::TEXT, ARRAY[1727, 1728]::BIGINT[]),
    (437::BIGINT, 'De los mejores profes que he tenido, super claro y presentaciones faciles de entender, sus clases son dinamicas y sus examenes son 100% de lo que se ven en tareas y quices. Es capaz de eximir a los estudiantes del examen final que tienen buena nota'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'c808dbc041887161e9440da6fa98926f1d7772c81b98b94d729a1b5e58f0fe2f'::TEXT, ARRAY[963, 1728, 1743]::BIGINT[]),
    (437::BIGINT, 'explica muy bien, cada clase se hace un trabajo en clase, estos ayudan mucho para el examen. Los exámenes tienen muy pocos puntos y si califica un toque duro pero lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'da5e26328463f2eb934e185c804d57be3b3d93aae82c08eb3862ab89a3a28485'::TEXT, ARRAY[963, 1728, 1743]::BIGINT[]),
    (437::BIGINT, 'Muy buen profesor, tiene mucha paciencia y sus precentaciones son muy completas, es conciente de la dificultad del curso y es muy compasivo, explica muy bien y da todos los recursos y mas para que estudien y esten al dia con la materia'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores']::TEXT[], '2025-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'f71c6979ec01b73dc4dc5d7943da1a5d60a236f6df0cf7fea9340224b09afa4e'::TEXT, ARRAY[963]::BIGINT[]),
    (437::BIGINT, 'Muy buen profesor, explica muy claro, hace varios quizzes y deja bastante practica para los exámenes, al final deja un examen final de la materia de todo el semestre pero se pueden eximir'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '62e4bc2336aaea517c29cfb0d4e311bca9d6ba6a1a91479cca32f1a13871189b'::TEXT, ARRAY[963]::BIGINT[]),
    (437::BIGINT, 'Es muy buen profe y se aprende mucho con el. Si hay muchos trabajos durante todo el curso, pero todo es en grupo. Es importante tener un buen grupo para trabajar. Para el proyecto si es exigente, pero es muy accesible para dudas y consultas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '92bdee1ca859fd0b4a23a6e91ea6f4f039a3b1d5ee29e3f63ccae1d8b10f8494'::TEXT, ARRAY[1736]::BIGINT[]),
    (437::BIGINT, 'El mejor profe.El curso es pesado pero se aprende demasiado con él. Es muy buena persona y ayuda lo más que puede al estudiante, su tiempo de consulta es bastante flexible y siempre esta dispuesto a ayudar. Es cuestión de organirzarse y elegir un buen equipo de trabajo para el proyecto.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2025-07-02T00:00:00+00:00'::TIMESTAMPTZ, '8d20311e8b6294de9ad91a8412b997bc0b57f0ba03bd912d56ba72ffa4bd8fce'::TEXT, ARRAY[1727, 1736]::BIGINT[]),
    (437::BIGINT, 'Siempre deja prácticas o evaluaciones extra con el pretexto de dar puntos extra pero nunca lo hace.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2025-06-30T00:00:00+00:00'::TIMESTAMPTZ, '0a52616621b43b7d5dc9fc47d1fcaf2b266cec10845ab13e5cdf9d3112dac9eb'::TEXT, ARRAY[1727, 1736]::BIGINT[]),
    (437::BIGINT, 'El profe es muy bueno, el curso es pesado, pero el enseña bien y da mucha ayuda si uno la solicita. El proyecto fue lo peor, el no previo lo que conllevaba hacerlo y se hizo más pesado de lo que era. Califica duro, pero enseña excelente y es una gran persona. Muy buena opción para matricular.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '4acf92553a9f11a0ffb73f2dd3737f77a1d228edf2d5962879cc1489139e5a4e'::TEXT, ARRAY[1736]::BIGINT[]),
    (437::BIGINT, 'El profesor no planificó bien los trabajos con instituciones externas, lo que nos dejó mal parados frente a otras personas. Tampoco dio apoyo durante las consultas, y muchas veces su trato fue pasivo-agresivo. A la hora de calificar, se contradijo con lo que se vio en clase.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, '028642b10a38985747dc93ca0a147361b56f668c009c8172413f18b2b26562c2'::TEXT, ARRAY[1736]::BIGINT[]),
    (437::BIGINT, 'Buen profe, comprensivo y accesible. El asistente que es un toque estricto y a veces se contradice :/ Pero es una muy buena opción :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-12-19T00:00:00+00:00'::TIMESTAMPTZ, 'b2f773e48c5b120c61c23e00dbe5edde1d59a43a4c46398ca46bf5704e0dd44b'::TEXT, ARRAY[1727]::BIGINT[]),
    (437::BIGINT, 'Excelente profe, matricule sin miedo. Si puede llévelo en grupo, hay muchos trabajos en grupo. Ayuda mucho y es muy accesible, se aprende mucho, pero hay que dedicarle tiempo y esfuerzo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, '41c3711cd0e4bac3998c5b96ea3ccd7b909a91a8ac664d31c9e827c53c566eb6'::TEXT, ARRAY[1727]::BIGINT[]),
    (437::BIGINT, 'BUENISIMO, DE UNA'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'dac58fcd4afca57ccd491bd0af7ad4c68c5b6758c4fa31419c69cdb5f8639c6e'::TEXT, ARRAY[1727]::BIGINT[]),
    (437::BIGINT, 'Excelente profe, ayuda un montón, las clases son claras y hace ejercicios que ayudan para entender y para el examen. Siempre ayuda y está dispuesto para los estudiantes. Matricular con él siempre es una excelente opción.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2024-11-19T00:00:00+00:00'::TIMESTAMPTZ, '9ecc8d2bc620d0170daa15387b344321e77c21c41b784402fc945941e290ac58'::TEXT, ARRAY[1727]::BIGINT[]),
    (437::BIGINT, 'El profe es una teja y explica súper bien, sin embargo los exámenes pueden ser muy volados, por lo que sí o sí tiene que andar muy bien preparado desde semana 1, la materia como tal no es complicada, pero es MUCHA, así que es un curso para no tomárselo a la ligera.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'a45b77f40878e9ecdf8e679caa9483cc9c18d6d91464f2f2589add30c618ff14'::TEXT, ARRAY[963]::BIGINT[]),
    (437::BIGINT, 'Es un muy buen profe, pero califica demasiado duro. Los exámenes son complicados. Lleve la materia al día, haga todas las prácticas y súbalas al TD aunque no tengan valor porque al final da puntos extra. Lo recomiendo porque sí se aprende bien, pero si no quiere complicaciones búsquese otro profe.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Da crédito extra']::TEXT[], '2024-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'fa5946de217c69eb17e09b39bf4a45a67c9f53fbef2771b258a0ce08c19a2934'::TEXT, ARRAY[963]::BIGINT[]),
    (437::BIGINT, 'Es un excelente profesor, califica un duro, y sus exámenes son bastante largos, solo lleve todo al día entregue todo y practique bastante, con eso el curso se pasa bien, además, es un profe que explica bien y siempre te puede aclarar dudas, sin duda si puede matricule con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2024-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'cf3e0eb485e8e76f468ce3c7ec3e5e1095bdcf14c5700ac0a405f9398e452df1'::TEXT, ARRAY[1446]::BIGINT[]),
    (437::BIGINT, 'Es un profe que se nota que le gusta enseñar, explica de la manera mas clara y da bastante practica lo cual es muy util en esta clase de cursos. Tiene una excelte actitud cuando se trata de resolver dudas, es una persona respetuosa y amable'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-15T00:00:00+00:00'::TIMESTAMPTZ, '9279773ec900981bb43fbd8a9164b65f7c9c2e767b22f5ffbd931c577fc7305f'::TEXT, ARRAY[1446]::BIGINT[]),
    (437::BIGINT, 'Muy buen profe, las clases pueden llegar a ser un toque largas y siempre hace quices, todas las semanas, entonces la asistencia es obligatoria. Las evaluaciones son equivalentes a lo que se ve en clases y con ejercicios parecidos a las prácticas y quices. No dude en matricular con él, se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'f9cf96a85b3eeb6b631862d3f6c516535080304fbbe5b321ede9d73729217da5'::TEXT, ARRAY[1743]::BIGINT[]),
    (437::BIGINT, 'Es un excelente profe!! Explica la materia muy bien y posee amplio conocimiento. Hace trabajos en clase y quices semanales, por lo que la asistencia es importante (son buena preparación para los exámenes). Es muy atento a consultas y dudas de los estudiantes y las atiende de la mejor manera? 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'ec322858ae08c791bf039081c7c5dcabe514ab39992709436be8ede7d21b0dd3'::TEXT, ARRAY[963]::BIGINT[]),
    (437::BIGINT, 'Muy buen profe, explica bien y bastante claro, además que siempre responde de manera respetuosa las dudas. Exime del examen final. Hay quices y trabajos en clase cada semana eso si, faltar es tirar el curso por la ventana.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'd06b7c1f2e0e64e4400f9f9627836b6ce283bc8df67b8b36e33a5ace505dde8d'::TEXT, ARRAY[963]::BIGINT[]),
    (437::BIGINT, 'Es un excelente profesor, super claro al explicar, siempre pensando en los estudiantes... el mejor del TEC!!!! matriculen sin pensarlo con él!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'ab753f62001a7f8fe421935905bf068b6af3fd4ae782ed4bb91442419524167f'::TEXT, ARRAY[963]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
